"use strict";(globalThis.webpackChunkgrc||=[]).push([[51283],{26883(e){e.exports=JSON.parse('{"citeKey":"sun2014concurrentaverage","slug":"sun-2014-concurrent-average-f9f1","title":"Concurrent Average Memory Access Time","authors":["X.-H. Sun","D. Wang"],"venue":"IEEE Computer, vol. 47, no. 5, pp. 74-80","type":"Journal","entryType":"article","date":"May, 2014","year":2014,"era":"iit","month":5,"doi":"10.1109/mc.2013.227","abstract":"Traditional memory performance metrics, such as average memory access time (AMAT), are designed for sequential data accesses and can prove misleading for contemporary cache technologies that increasingly rely on access concurrency. C-AMAT, a new performance metric, accounts for concurrency at both the component and system levels for modern memory design.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2014/sun-2014-concurrent-average-f9f1.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);